import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;abstract class Room{String id;Room(String i){id=i;}abstract double price(long nights);}class StandardRoom extends Room{StandardRoom(String i){super(i);}double price(long n){return 100*n;}}class DeluxeRoom extends Room{DeluxeRoom(String i){super(i);}double price(long n){return 150*n;}}class Suite extends Room{Suite(String i){super(i);}double price(long n){return 250*n;}}class Customer{String name;Customer(String n){name=n;}}class Reservation{Room room;Customer customer;LocalDate start,end,deadline;boolean active=true;Reservation(Room r,Customer c,LocalDate s,LocalDate e,LocalDate d){room=r;customer=c;start=s;end=e;deadline=d;}boolean overlaps(LocalDate s,LocalDate e){return active&&s.isBefore(end)&&e.isAfter(start);}double price(){return room.price(ChronoUnit.DAYS.between(start,end));}void cancel(LocalDate now){if(now.isAfter(deadline))throw new IllegalStateException();active=false;}}class Hotel{List<Reservation> reservations=new ArrayList<>();boolean available(Room r,LocalDate s,LocalDate e){for(Reservation x:reservations)if(x.room==r&&x.overlaps(s,e))return false;return true;}Reservation reserve(Room r,Customer c,LocalDate s,LocalDate e,LocalDate d){if(!available(r,s,e))throw new IllegalStateException();Reservation x=new Reservation(r,c,s,e,d);reservations.add(x);return x;}}public class Main{public static void main(String[]a){}}